package com.bank.maxsubarray;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds the best contiguous net-gain stretch for National Bank of India.
public class MaxSubarrayAnalyzer {
    private static final Logger log = Logger.getLogger(MaxSubarrayAnalyzer.class.getName());

    // Largest contiguous subarray sum (Kadane's). O(n), O(1).
    public BigDecimal bestContiguousGain(BigDecimal[] flows) {
        if (flows == null || flows.length == 0) {
            throw new IllegalArgumentException("flows must be non-empty");
        }
        BigDecimal current = flows[0];     // best sum ending at index 0
        BigDecimal best = flows[0];        // best sum seen anywhere
        int start = 0, tentativeStart = 0, end = 0;
        for (int i = 1; i < flows.length; i++) {
            BigDecimal extend = current.add(flows[i]);
            if (flows[i].compareTo(extend) > 0) {
                current = flows[i];        // start fresh: past would only hurt
                tentativeStart = i;
            } else {
                current = extend;          // extend the running stretch
            }
            if (current.compareTo(best) > 0) {
                best = current;            // new best stretch total
                start = tentativeStart;
                end = i;
            }
        }
        final int s = start, e = end;
        final BigDecimal result = best;
        log.info(() -> "Best gain = " + result + " over days [" + s + ".." + e + "]");
        return best;
    }
}
