package com.bank.maxsubarray;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: best net-gain stretch for Rajesh.
public class MaxSubarrayDemo {
    private static final Logger log = Logger.getLogger(MaxSubarrayDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        MaxSubarrayAnalyzer analyzer = new MaxSubarrayAnalyzer();

        // Rajesh (SAV2001) daily net cash flow (in thousands).
        BigDecimal[] flows = { bd("-2"), bd("1"), bd("-3"), bd("4"),
                               bd("-1"), bd("2"), bd("1"), bd("-5"), bd("4") };
        BigDecimal gain = analyzer.bestContiguousGain(flows);
        log.info(() -> "Best contiguous net gain for Rajesh = " + gain);
    }
}
